-- 048: a company superadmin cannot change another superadmin (or itself) by direct table write or RPC; only a platform operator can.
-- Role-vs-role adversarial matrix: actors Owner(operator), superadmin A, company admin C, employee E; targets superadmin B, admin C, self.
begin;
create function extensions.sh48_rows(q text) returns int language plpgsql as $f$ declare n int; begin execute q; get diagnostics n=row_count; return n; end $f$;
grant usage on schema extensions to anon, authenticated, service_role;
grant execute on all functions in schema extensions to anon, authenticated, service_role;
select extensions.plan(128);
